<template>
 <div v-if="show" class="release-modal-backdrop" @click.self="$emit('close')"><section class="release-modal capability-panel" role="dialog" aria-modal="true" aria-label="工具与技能"><header><h2>工具与技能</h2><button @click="$emit('close')" aria-label="关闭工具面板">×</button></header><div class="release-tabs"><button :disabled="busy" v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{ t.label }}</button></div><p v-if="error" class="release-error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
 <div v-if="tab==='mcp'"><div v-for="s in servers" :key="s.id" class="capability-row"><b>{{ s.name }}</b><span>{{ s.enabled?'已启用':'已关闭' }} · {{ s.transport }}</span><button :disabled="busy" @click="editServer(s)">编辑</button><button :disabled="busy||!s.enabled" @click="loadTools(s)">连接并查看工具</button><button :disabled="busy" @click="removeServer(s)">删除</button></div>
 <div class="release-button-row"><button v-if="!servers.some(s=>s.id==='prime')" @click="newPrime">添加内置质数工具</button><button :disabled="busy" @click="newServer">添加 MCP 服务</button></div><form v-if="serverForm" @submit.prevent="saveServer"><label>名称<input v-model="serverForm.name" maxlength="80" required/></label><label>传输方式<select v-model="serverForm.transport" :disabled="serverForm.builtin"><option value="http">HTTP（推荐）</option><option value="sse">旧版 HTTP SSE</option><option v-if="serverForm.transport==='builtin'" value="builtin">内置工具</option><option v-if="offline" value="stdio">本机 stdio</option></select></label><label v-if="['http','streamable-http','sse'].includes(serverForm.transport)">{{ serverForm.transport==='sse'?'SSE 地址':'MCP 地址' }}<input v-model="serverForm.url" :placeholder="serverForm.transport==='sse'?'https://example.com/sse':'https://example.com/mcp'"/></label><small v-if="['http','streamable-http','sse'].includes(serverForm.transport)">请按服务方提供的协议选择 Streamable HTTP 或旧版 SSE。</small><label v-else-if="serverForm.transport==='stdio'">启动命令（JSON 数组）<textarea v-model="command" rows="3" placeholder='["java","-jar","/path/to/tool.jar"]'/></label><p v-if="serverForm.transport==='builtin'">保存后点击「连接并查看工具」即可试用。</p><label v-if="['http','streamable-http','sse'].includes(serverForm.transport)">请求头（JSON，同地址留空保留；换地址需重填）<textarea v-model="headers" rows="2" placeholder='{"Authorization":"Bearer …"}'/></label><label class="release-check"><input type="checkbox" v-model="serverForm.enabled"/>启用服务</label><label class="release-check"><input type="checkbox" v-model="serverForm.allowModelCalls"/>允许模型调用此服务的工具</label><button class="release-primary" :disabled="busy">保存服务</button></form>
 <div v-if="tools.length"><h3>{{ toolServer?.name }} 的工具</h3><div v-for="t in tools" :key="t.name" class="capability-row"><button :disabled="busy" @click="selectTool(t)">{{ t.name }}</button><span>{{ t.description }}</span></div><template v-if="selectedTool"><h4>{{ selectedTool.name }}</h4><label v-if="toolServer?.id==='prime'">要判断的正整数<input v-model="primeNumber" inputmode="numeric" pattern="[0-9]+"/></label><template v-else><pre>{{ JSON.stringify(selectedTool.parameters,null,2) }}</pre><label>工具参数（JSON）<textarea v-model="argumentsText" rows="4"/></label></template><button :disabled="busy" @click="runTool">运行工具</button></template></div><pre v-if="toolResult">{{ toolResult }}</pre></div>
 <div v-if="tab==='skills'"><div v-for="s in skills" :key="s.name" class="capability-row"><div class="capability-skill-name"><b>{{ skillLabel(s) }}</b><small v-if="skillLabel(s)!==s.name">{{ s.name }}</small><p v-if="s.description">{{ s.description }}</p></div><span>{{ s.enabled?'已启用':'已关闭' }}</span><button :disabled="busy" @click="editSkill(s)">编辑</button><button :disabled="busy" @click="toggleSkill(s)">{{ s.enabled?'停用':'启用' }}</button><button :disabled="busy" @click="removeSkill(s)">删除</button></div><button :disabled="busy" @click="editSkill({name:'new-skill',description:'',enabled:true,keywords:[],instructions:'',mcpTools:[]},true)">创建技能</button><form v-if="skillForm" @submit.prevent="saveSkill"><label>名称<input v-model="skillForm.name" :readonly="!creatingSkill" required maxlength="80" placeholder="例如 reading-reminder"/></label><small v-if="creatingSkill">名称使用 1–80 位英文字母、数字、下划线或连字符，保存后固定。中文可填在说明中。</small><label>说明<input v-model="skillForm.description"/></label><template v-if="!builtinSkill"><label>使用方式<select v-model="triggerForm.mode" @change="syncTrigger"><option value="keywords">关键词触发</option><option value="always">每次聊天</option><option value="schedule">仅定时</option><option value="keywords_and_schedule">关键词和定时</option></select></label><label v-if="['keywords','keywords_and_schedule'].includes(triggerForm.mode)">关键词（逗号分隔，必填）<input v-model="keywords" required/></label><div v-if="['schedule','keywords_and_schedule'].includes(triggerForm.mode)"><label>每日时间<input type="time" v-model="triggerForm.time" required @change="syncTrigger(true)"/></label><label>时区<input v-model="triggerForm.zone" required @change="syncTrigger"/></label><label><input type="checkbox" v-model="triggerForm.enabled" @change="syncTrigger"/>启用定时与主动投递</label><p>定时投递需要保持现实陪伴篇章打开，开启主动搭话，并满足空闲时间。停用技能会关闭投递。</p><small>修改每日时间会清除高级配置中的 cron。</small></div></template><p v-else>内置技能的触发规则可在高级配置中调整。</p><label>技能指令<textarea v-model="skillForm.instructions" rows="7" maxlength="12000"/></label><details><summary>高级配置（JSON，可选）</summary><label>JSON：schedule、source、proactive、mcpTools<textarea v-model="advanced" @change="readAdvancedTrigger" rows="5" aria-describedby="skill-advanced-help"/></label><details id="skill-advanced-help"><summary>查看示例与字段说明</summary><p>应用示例后需保存。示例默认关闭定时和主动投递。</p><pre>{{ advancedExample }}</pre><button type="button" @click="advanced=advancedExample;readAdvancedTrigger()">用示例替换</button><ul><li>schedule.enabled 开启定时。hour 为 0–23，minute 为 0–59，zone 为时区（例如 Asia/Shanghai）。若填写 cron，需使用六段表达式，优先于 hour、minute。</li><li>proactive.enabled 开启主动投递。自建定时技能需同时开启 schedule 和 proactive。</li><li>mcpTools 填工具名，例如 ["echo"]。范围限于已授权工具，填 [] 时沿用授权范围。</li><li>source 仅供内置 AI 日报技能 ai-daily-juya 使用。</li></ul></details></details><button class="release-primary" :disabled="busy">保存技能</button></form></div>

 </section></div>
</template>
<script setup>
import {ref,watch,computed,onBeforeUnmount} from 'vue'
import {json,distribution} from './api.mjs'
import {parseConfigJson,parseCommand,parseHeaders,parseAdvanced,advancedExample} from './capabilityConfig.mjs'
import {readTriggerForm,writeTriggerForm} from './skillTriggerForm.mjs'
const editingSkillName=ref(''),creatingSkill=ref(false)
const triggerForm=ref({}),builtinSkill=computed(()=>['ai-daily-juya','weather-lookup'].includes(editingSkillName.value))
function readAdvancedTrigger(){try{triggerForm.value=readTriggerForm({...skillForm.value,...parseAdvanced(advanced.value),triggerMode:triggerForm.value.mode})}catch(e){error.value=e.message}}
function syncTrigger(clearCron=false){try{const a=parseAdvanced(advanced.value);if(clearCron===true&&a.schedule)delete a.schedule.cron;const v=writeTriggerForm(skillForm.value,a,triggerForm.value,keywords.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean));advanced.value=JSON.stringify({schedule:v.schedule,source:v.source,proactive:v.proactive,mcpTools:v.mcpTools||[]},null,2)}catch(e){error.value=e.message}}
const props=defineProps({show:Boolean,initialTab:{type:String,default:'mcp'}})
defineEmits(['close'])
const offline=distribution==='offline',tabs=[{id:'mcp',label:'MCP 工具'},{id:'skills',label:'技能'}]
function skillLabel(skill){return ({'ai-daily-juya':'AI 日报','weather-lookup':'天气查询'})[skill.name]||skill.name}
const primeNumber=ref('97')
const tab=ref('mcp'),error=ref(''),notice=ref(''),busy=ref(false),servers=ref([]),skills=ref([]),serverForm=ref(null),skillForm=ref(null),tools=ref([]),toolServer=ref(null),selectedTool=ref(null),toolResult=ref(''),argumentsText=ref('{}'),command=ref('[]'),headers=ref(''),keywords=ref(''),advanced=ref('{}')
let epoch=0
function resetPanel(){epoch++;busy.value=false;servers.value=[];skills.value=[];serverForm.value=null;skillForm.value=null;clearTools();error.value='';notice.value=''}
function clearTools(){tools.value=[];toolServer.value=null;selectedTool.value=null;toolResult.value='';argumentsText.value='{}';primeNumber.value='97'}
async function run(fn){if(busy.value)return;const current=epoch;busy.value=true;error.value='';notice.value='';const request=async(...args)=>{const value=await json(...args);if(current!==epoch)throw new Error('stale');return value};try{await fn(request)}catch(e){if(current===epoch)error.value=e.message}finally{if(current===epoch)busy.value=false}}
async function load(){await run(async(request)=>{[servers.value,skills.value]=await Promise.all([request('/api/mcp/servers'),request('/api/skills')])})}
function newPrime(){editServer({id:'prime',name:'内置质数工具',builtin:true,transport:'builtin',enabled:true,allowModelCalls:false})}
function selectTool(tool){selectedTool.value=tool;argumentsText.value='{}';primeNumber.value='97';toolResult.value=''}
function newServer(){editServer({name:'',transport:'http',url:'',enabled:false,allowModelCalls:false})}
function editServer(value){epoch++;busy.value=false;clearTools();serverForm.value={...value,transport:value.transport==='streamable-http'?'http':value.transport||'sse'};command.value=JSON.stringify(value.command||[]);headers.value=''}
async function saveServer(){await run(async(request)=>{const value={...serverForm.value};if(value.transport==='stdio')value.command=parseCommand(command.value);if(headers.value.trim())value.headers=parseHeaders(headers.value);await request('/api/mcp/servers',value,'POST');servers.value=await request('/api/mcp/servers');serverForm.value=null;notice.value='MCP 配置已保存'})}
async function removeServer(s){clearTools();await run(async(request)=>{await request(`/api/mcp/servers/${s.id}`,undefined,'DELETE');servers.value=await request('/api/mcp/servers');if(serverForm.value?.id===s.id)serverForm.value=null})}
async function loadTools(s){clearTools();await run(async(request)=>{tools.value=await request(`/api/mcp/servers/${s.id}/tools`);toolServer.value=s;selectedTool.value=null;toolResult.value='';notice.value=`已连接，发现 ${tools.value.length} 个工具`})}
function primeArgument(){if(!/^[0-9]+$/.test(primeNumber.value)||!Number.isSafeInteger(Number(primeNumber.value))||Number(primeNumber.value)<1)throw new Error('请输入有效的正整数（不超过 9007199254740991）');return Number(primeNumber.value)}
async function runTool(){await run(async(request)=>{toolResult.value='';const r=await request(`/api/mcp/servers/${toolServer.value.id}/tools/${encodeURIComponent(selectedTool.value.name)}`,toolServer.value.id==='prime'?{number:primeArgument()}:parseConfigJson(argumentsText.value,'工具参数'),'POST');toolResult.value=r.result})}
function editSkill(s,isNew=false){creatingSkill.value=isNew;triggerForm.value=readTriggerForm(s,isNew);editingSkillName.value=s.name;skillForm.value={...s};keywords.value=(s.keywords||[]).join(',');advanced.value=JSON.stringify({schedule:s.schedule,source:s.source,proactive:s.proactive,mcpTools:s.mcpTools||[]},null,2)}
async function saveSkill(){await run(async(request)=>{const current=skills.value.find(s=>s.name===editingSkillName.value);const words=keywords.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean);const value=builtinSkill.value?{...skillForm.value,...parseAdvanced(advanced.value)}:writeTriggerForm(skillForm.value,parseAdvanced(advanced.value),triggerForm.value,words);if(!creatingSkill.value)value.name=editingSkillName.value;value.enabled=current?.enabled??skillForm.value.enabled;await request('/api/skills',value,'POST');skills.value=await request('/api/skills');skillForm.value=null;notice.value='技能已保存'})}
async function toggleSkill(s){await run(async(request)=>{await request(`/api/skills/${s.name}/toggle`,{},'PUT');skills.value=await request('/api/skills');if(skillForm.value&&editingSkillName.value===s.name)skillForm.value.enabled=skills.value.find(item=>item.name===s.name)?.enabled??false})}
async function removeSkill(s){await run(async(request)=>{await request(`/api/skills/${s.name}`,undefined,'DELETE');skills.value=await request('/api/skills');if(editingSkillName.value===s.name)skillForm.value=null})}
watch(()=>[props.show,props.initialTab],()=>{resetPanel();if(props.show){tab.value=props.initialTab;load()}},{immediate:true,flush:'sync'})
onBeforeUnmount(resetPanel)
</script>
